use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** I-Assm: Integration constraint on ArduPilot's incoming event data port EthernetFramesRx
  *
  * assume OnlyPermittedFrames
  */
pub fn I_Assm_EthernetFramesRx(EthernetFramesRx: SW::StructuredEthernetMessage_i) -> bool
{
  !(GumboLib::isMalformedFrame(EthernetFramesRx)) & GumboLib::isIPV4(EthernetFramesRx) &
    GumboLib::isTCP(EthernetFramesRx) &
    GumboLib::isPortWhitelisted(EthernetFramesRx)
}

/** I-Assm: Integration constraint on ArduPilot's incoming event data port EthernetFramesRx
  *
  * assume OnlyPermittedFrames
  */
pub fn I_Assm_Guard_EthernetFramesRx(EthernetFramesRx: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    EthernetFramesRx.is_some(),
    I_Assm_EthernetFramesRx(EthernetFramesRx.unwrap())
  )
}

/** I-Guar: Integration constraint on ArduPilot's outgoing event data port EthernetFramesTx
  *
  * guarantee TxOut_IPv4OrARP
  *  ArduPilot emits only IPv4 or ARP frames.
  */
pub fn I_Guar_EthernetFramesTx(EthernetFramesTx: SW::StructuredEthernetMessage_i) -> bool
{
  GumboLib::txExpected(EthernetFramesTx)
}

/** I-Guar: Integration constraint on ArduPilot's outgoing event data port EthernetFramesTx
  *
  * guarantee TxOut_IPv4OrARP
  *  ArduPilot emits only IPv4 or ARP frames.
  */
pub fn I_Guar_Guard_EthernetFramesTx(EthernetFramesTx: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  implies!(
    EthernetFramesTx.is_some(),
    I_Guar_EthernetFramesTx(EthernetFramesTx.unwrap())
  )
}

/** IEP-Post: Initialize Entrypoint Post-Condition
  *
  * @param api_EthernetFramesTx outgoing event data port
  */
pub fn initialize_IEP_Post(api_EthernetFramesTx: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  // I-Guar-Guard: Integration constraints for ArduPilot's outgoing ports"
  I_Guar_Guard_EthernetFramesTx(api_EthernetFramesTx)
}

/** CEP-Pre: Compute Entrypoint Pre-Condition for ArduPilot
  *
  * @param api_EthernetFramesRx incoming event data port
  */
pub fn compute_CEP_Pre(api_EthernetFramesRx: Option<SW::StructuredEthernetMessage_i>) -> bool
{
  // I-Assm-Guard: Integration constraints for ArduPilot's incoming ports
  let r0: bool = I_Assm_Guard_EthernetFramesRx(api_EthernetFramesRx);

  return r0;
}

